insert into public.quizzes
  (slug, title, description, quiz_type, difficulty, language, category_id,
   questions, results, tags, estimated_minutes, status,
   is_featured, is_ai_generated, published_at)
values (
  'en-bleach-trivia',
  'Bleach Trivia: Soul Reapers, Zanpakuto and Arcs',
  'Soul Reapers, Hollows and zanpakuto releases: from Karakura Town to Hueco Mundo. How well do you know Tite Kubo''s shonen classic?',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'anime-manga'),
  '[{"id":"q1","question":"Who created the Bleach manga?","options":[{"id":"a","text":"Eiichiro Oda","is_correct":false},{"id":"b","text":"Tite Kubo","is_correct":true},{"id":"c","text":"Masashi Kishimoto","is_correct":false},{"id":"d","text":"Akira Toriyama","is_correct":false}],"explanation":"Tite Kubo serialized Bleach in Weekly Shonen Jump from 2001 to 2016."},{"id":"q2","question":"How does Ichigo Kurosaki first gain Soul Reaper powers?","options":[{"id":"a","text":"He is born with them","is_correct":false},{"id":"b","text":"Rukia Kuchiki transfers hers to him","is_correct":true},{"id":"c","text":"He trains for years under Urahara","is_correct":false},{"id":"d","text":"A Hollow bite awakens them","is_correct":false}],"explanation":"Rukia pierces Ichigo with her zanpakuto to share her powers — and he ends up absorbing almost all of them."},{"id":"q3","question":"What is the name of Ichigo''s zanpakuto?","options":[{"id":"a","text":"Senbonzakura","is_correct":false},{"id":"b","text":"Hyorinmaru","is_correct":false},{"id":"c","text":"Zangetsu","is_correct":true},{"id":"d","text":"Zabimaru","is_correct":false}],"explanation":"Zangetsu, the ''slaying moon''. Senbonzakura belongs to Byakuya, Hyorinmaru to Hitsugaya and Zabimaru to Renji."},{"id":"q4","question":"What are the masked, corrupted souls that Soul Reapers hunt?","options":[{"id":"a","text":"Arrancar","is_correct":false},{"id":"b","text":"Hollows","is_correct":true},{"id":"c","text":"Quincies","is_correct":false},{"id":"d","text":"Vizards","is_correct":false}],"explanation":"Hollows are corrupted souls; Arrancar are Hollows that tore off their masks to gain Soul Reaper powers."},{"id":"q5","question":"What is the military force of Soul Society called?","options":[{"id":"a","text":"The Gotei 13","is_correct":true},{"id":"b","text":"The Espada","is_correct":false},{"id":"c","text":"The Royal Guard","is_correct":false},{"id":"d","text":"The Onmitsukido","is_correct":false}],"explanation":"The Gotei 13 fields thirteen divisions; the Espada serve Aizen and the Onmitsukido is the stealth force."},{"id":"q6","question":"Which captain fakes his death and betrays Soul Society?","options":[{"id":"a","text":"Shunsui Kyoraku","is_correct":false},{"id":"b","text":"Kenpachi Zaraki","is_correct":false},{"id":"c","text":"Sosuke Aizen","is_correct":true},{"id":"d","text":"Toshiro Hitsugaya","is_correct":false}],"explanation":"Aizen, captain of the Fifth Division, reveals the conspiracy was his and defects to Hueco Mundo."},{"id":"q7","question":"Uryu Ishida belongs to which order of spiritually aware humans?","options":[{"id":"a","text":"The Fullbringers","is_correct":false},{"id":"b","text":"The Quincies","is_correct":true},{"id":"c","text":"The Bounts","is_correct":false},{"id":"d","text":"The Vizards","is_correct":false}],"explanation":"Uryu is introduced as the last Quincy, an order of archers who destroy Hollows instead of purifying them."},{"id":"q8","question":"What is the final arc of the Bleach manga?","options":[{"id":"a","text":"The Arrancar arc","is_correct":false},{"id":"b","text":"The Lost Agent arc","is_correct":false},{"id":"c","text":"The Soul Society arc","is_correct":false},{"id":"d","text":"The Thousand-Year Blood War","is_correct":true}],"explanation":"The manga closed in 2016 with the Thousand-Year Blood War, the war against the Quincy empire."}]'::jsonb,
  null,
  array['bleach', 'anime', 'manga', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
