values (
  'es-trivia-bleach',
  'Trivia de Bleach: shinigamis, zanpakuto y sagas',
  'Shinigamis, hollows y liberaciones de zanpakuto: de la ciudad de Karakura al Hueco Mundo. ¿Cuánto conoces del clásico de Tite Kubo?',
  'trivia',
  'medium',
  'es',
  (select id from public.categories where slug = 'anime-manga'),
  '[{"id":"q1","question":"¿Quién creó el manga de Bleach?","options":[{"id":"a","text":"Tite Kubo","is_correct":true},{"id":"b","text":"Eiichiro Oda","is_correct":false},{"id":"c","text":"Masashi Kishimoto","is_correct":false},{"id":"d","text":"Gege Akutami","is_correct":false}],"explanation":"Tite Kubo lo publicó en la Weekly Shonen Jump entre 2001 y 2016."},{"id":"q2","question":"¿Quién le transfiere a Ichigo sus poderes de shinigami?","options":[{"id":"a","text":"Kisuke Urahara","is_correct":false},{"id":"b","text":"Rukia Kuchiki","is_correct":true},{"id":"c","text":"Yoruichi Shihoin","is_correct":false},{"id":"d","text":"Isshin Kurosaki","is_correct":false}],"explanation":"Rukia lo atraviesa con su zanpakuto para compartir sus poderes, e Ichigo acaba absorbiendo casi todos."},{"id":"q3","question":"¿Cómo se llama la zanpakuto de Ichigo?","options":[{"id":"a","text":"Zabimaru","is_correct":false},{"id":"b","text":"Senbonzakura","is_correct":false},{"id":"c","text":"Zangetsu","is_correct":true},{"id":"d","text":"Hyorinmaru","is_correct":false}],"explanation":"Zangetsu. Senbonzakura es de Byakuya, Hyorinmaru de Hitsugaya y Zabimaru de Renji."},{"id":"q4","question":"¿Cómo se llaman las almas corruptas con máscara que cazan los shinigami?","options":[{"id":"a","text":"Vizards","is_correct":false},{"id":"b","text":"Arrancar","is_correct":false},{"id":"c","text":"Hollows","is_correct":true},{"id":"d","text":"Quincy","is_correct":false}],"explanation":"Los hollows son almas corruptas; los Arrancar son hollows que se arrancaron la máscara."},{"id":"q5","question":"¿Cómo se llama la fuerza militar de la Sociedad de Almas?","options":[{"id":"a","text":"El Gotei 13","is_correct":true},{"id":"b","text":"Los Espada","is_correct":false},{"id":"c","text":"La Guardia Real","is_correct":false},{"id":"d","text":"La Onmitsukido","is_correct":false}],"explanation":"El Gotei 13 reúne trece divisiones; los Espada sirven a Aizen y la Onmitsukido es la fuerza de sigilo."},{"id":"q6","question":"¿Qué capitán finge su muerte y traiciona a la Sociedad de Almas?","options":[{"id":"a","text":"Sosuke Aizen","is_correct":true},{"id":"b","text":"Byakuya Kuchiki","is_correct":false},{"id":"c","text":"Kenpachi Zaraki","is_correct":false},{"id":"d","text":"Jushiro Ukitake","is_correct":false}],"explanation":"Aizen, capitán de la Quinta División, revela que todo era su plan y huye al Hueco Mundo."},{"id":"q7","question":"¿A qué orden de humanos espirituales pertenece Uryu Ishida?","options":[{"id":"a","text":"Los Fullbringers","is_correct":false},{"id":"b","text":"Los Quincy","is_correct":true},{"id":"c","text":"Los Bount","is_correct":false},{"id":"d","text":"Los Vizard","is_correct":false}],"explanation":"Uryu se presenta como el último Quincy, una orden de arqueros que destruye hollows en vez de purificarlos."},{"id":"q8","question":"¿En qué ciudad ficticia vive Ichigo?","options":[{"id":"a","text":"Hueco Mundo","is_correct":false},{"id":"b","text":"Karakura","is_correct":true},{"id":"c","text":"Seireitei","is_correct":false},{"id":"d","text":"Naruki","is_correct":false}],"explanation":"La ciudad de Karakura, tan rica en energía espiritual que atrae hollows. El Seireitei está en la Sociedad de Almas."}]'::jsonb,
  null,
  array['bleach', 'anime', 'manga', 'trivia']::text[],
