values (
  'en-haikyuu-trivia',
  'Haikyuu!! Trivia: Teams, Rivals and Rallies',
  'Crows against cats, the freak quick and the Battle at the Garbage Dump. Prove how much you know about Karasuno and the road to nationals.',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'anime-manga'),
  '[{"id":"q1","question":"Which high school do Hinata and Kageyama attend?","options":[{"id":"a","text":"Karasuno High","is_correct":true},{"id":"b","text":"Nekoma High","is_correct":false},{"id":"c","text":"Aoba Johsai","is_correct":false},{"id":"d","text":"Shiratorizawa Academy","is_correct":false}],"explanation":"Karasuno, the ''fallen champions'' — the flightless crows."},{"id":"q2","question":"What position does Kageyama play?","options":[{"id":"a","text":"Libero","is_correct":false},{"id":"b","text":"Wing spiker","is_correct":false},{"id":"c","text":"Setter","is_correct":true},{"id":"d","text":"Opposite hitter","is_correct":false}],"explanation":"Kageyama is the genius setter; Hinata plays middle blocker."},{"id":"q3","question":"What nickname did Kageyama get at Kitagawa Daiichi middle school?","options":[{"id":"a","text":"The King of the Court","is_correct":true},{"id":"b","text":"The Guardian Deity","is_correct":false},{"id":"c","text":"The Great Ace","is_correct":false},{"id":"d","text":"The Iron Wall","is_correct":false}],"explanation":"The ''King of the Court'' was an insult about his demanding tosses; he turns it into a title."},{"id":"q4","question":"What do Karasuno fans call Hinata and Kageyama''s lightning-fast attack?","options":[{"id":"a","text":"The jump float","is_correct":false},{"id":"b","text":"The freak quick","is_correct":true},{"id":"c","text":"The rolling thunder","is_correct":false},{"id":"d","text":"The sky block","is_correct":false}],"explanation":"The ''freak quick'' — Hinata spikes a ball he never even sees coming."},{"id":"q5","question":"The ''Battle at the Garbage Dump'' pits Karasuno against which rival school?","options":[{"id":"a","text":"Date Tech","is_correct":false},{"id":"b","text":"Fukurodani","is_correct":false},{"id":"c","text":"Nekoma","is_correct":true},{"id":"d","text":"Inarizaki","is_correct":false}],"explanation":"Nekoma, the cats — crows and cats fighting over scraps, hence the name."},{"id":"q6","question":"Who is Aoba Johsai''s star setter and captain?","options":[{"id":"a","text":"Toru Oikawa","is_correct":true},{"id":"b","text":"Hajime Iwaizumi","is_correct":false},{"id":"c","text":"Kenma Kozume","is_correct":false},{"id":"d","text":"Keiji Akaashi","is_correct":false}],"explanation":"Oikawa, Kageyama''s former senpai at Kitagawa Daiichi; Iwaizumi is his ace and best friend."},{"id":"q7","question":"Who defends Karasuno''s back line as libero?","options":[{"id":"a","text":"Kei Tsukishima","is_correct":false},{"id":"b","text":"Yu Nishinoya","is_correct":true},{"id":"c","text":"Tadashi Yamaguchi","is_correct":false},{"id":"d","text":"Asahi Azumane","is_correct":false}],"explanation":"Nishinoya, ''Karasuno''s Guardian Deity'' — short like Hinata, but fearless."},{"id":"q8","question":"Which former Karasuno ace inspired the undersized Hinata to play?","options":[{"id":"a","text":"The Little Giant","is_correct":true},{"id":"b","text":"The Iron Wall","is_correct":false},{"id":"c","text":"The Great King","is_correct":false},{"id":"d","text":"The Mad Dog","is_correct":false}],"explanation":"Tenma Udai, the ''Little Giant'' who once wore Karasuno''s number 10."}]'::jsonb,
  null,
  array['haikyuu', 'volleyball', 'anime', 'trivia']::text[],
  3,
  'published',
  false,
  false,
  now()
)
