is_correct":true},{"id":"b","text":"Daichi Sawamura","is_correct":false},{"id":"c","text":"Ryunosuke Tanaka","is_correct":false},{"id":"d","text":"Kei Tsukishima","is_correct":false}],"explanation":"Nishinoya, la ''Deidad Guardiana'' de Karasuno: bajito como Hinata, pero sin miedo."},{"id":"q7","question":"¿Qué excrack de Karasuno inspiró a Hinata pese a su estatura?","options":[{"id":"a","text":"El Muro de Hierro","is_correct":false},{"id":"b","text":"El Pequeño Gigante","is_correct":true},{"id":"c","text":"El Gran Rey","is_correct":false},{"id":"d","text":"El As del Este","is_correct":false}],"explanation":"Tenma Udai, el ''Pequeño Gigante'' que llevó el número 10 de Karasuno."},{"id":"q8","question":"¿Quién es el capitán de Karasuno?","options":[{"id":"a","text":"Koshi Sugawara","is_correct":false},{"id":"b","text":"Asahi Azumane","is_correct":false},{"id":"c","text":"Daichi Sawamura","is_correct":true},{"id":"d","text":"Keishin Ukai","is_correct":false}],"explanation":"Daichi es el capitán; Ukai es el entrenador y Sugawara el armador suplente."}]'::jsonb,
