values (
  'en-blue-lock-trivia',
  'Blue Lock Trivia: Ego, Strikers and Rankings',
  'Three hundred forwards enter a facility built to forge Japan''s ultimate egoist striker. Do you know Isagi, Bachira and the Neo Egoist League?',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'anime-manga'),
  '[{"id":"q1","question":"What is the Blue Lock program built to create?","options":[{"id":"a","text":"Japan''s best goalkeeper","is_correct":false},{"id":"b","text":"The world''s best egoist striker","is_correct":true},{"id":"c","text":"The perfect defense","is_correct":false},{"id":"d","text":"A new pro league","is_correct":false}],"explanation":"After Japan''s World Cup collapse, the union bets everything on forging a single egoist striker."},{"id":"q2","question":"Who runs Blue Lock as its head coach?","options":[{"id":"a","text":"Anri Teieri","is_correct":false},{"id":"b","text":"Jinpachi Ego","is_correct":true},{"id":"c","text":"Noel Noa","is_correct":false},{"id":"d","text":"Hirotoshi Buratsuta","is_correct":false}],"explanation":"Jinpachi Ego, the eccentric hired to produce the world''s best striker; Anri is the federation official who proposed him."},{"id":"q3","question":"Who is the series'' protagonist?","options":[{"id":"a","text":"Rin Itoshi","is_correct":false},{"id":"b","text":"Meguru Bachira","is_correct":false},{"id":"c","text":"Yoichi Isagi","is_correct":true},{"id":"d","text":"Seishiro Nagi","is_correct":false}],"explanation":"Yoichi Isagi, the forward who chose ego over regret after one pass cost him nationals."},{"id":"q4","question":"How many high-school forwards are locked inside Blue Lock?","options":[{"id":"a","text":"100","is_correct":false},{"id":"b","text":"300","is_correct":true},{"id":"c","text":"50","is_correct":false},{"id":"d","text":"1,000","is_correct":false}],"explanation":"Three hundred strikers enter; only the last one standing earns the Japan U-20 spot."},{"id":"q5","question":"Which team is Isagi assigned to in the first selection?","options":[{"id":"a","text":"Team V","is_correct":false},{"id":"b","text":"Team Z","is_correct":true},{"id":"c","text":"Team X","is_correct":false},{"id":"d","text":"Team W","is_correct":false}],"explanation":"Team Z, the lowest-ranked squad — where he meets Bachira, Chigiri and Kunigami."},{"id":"q6","question":"Which player chases the ''monster'' only he can see?","options":[{"id":"a","text":"Hyoma Chigiri","is_correct":false},{"id":"b","text":"Shoei Barou","is_correct":false},{"id":"c","text":"Meguru Bachira","is_correct":true},{"id":"d","text":"Rensuke Kunigami","is_correct":false}],"explanation":"Bachira grew up chasing an imaginary monster on the pitch; in Blue Lock he finally finds real ones."},{"id":"q7","question":"What is Sae Itoshi''s relation to Rin?","options":[{"id":"a","text":"His older brother","is_correct":true},{"id":"b","text":"His twin brother","is_correct":false},{"id":"c","text":"His cousin","is_correct":false},{"id":"d","text":"His teammate","is_correct":false}],"explanation":"Sae, a prodigy midfielder playing in Spain, is Rin''s older brother — and the standard he chases."},{"id":"q8","question":"Which Neo Egoist League club does Isagi choose?","options":[{"id":"a","text":"Ubers","is_correct":false},{"id":"b","text":"Manshine City","is_correct":false},{"id":"c","text":"PXG","is_correct":false},{"id":"d","text":"Bastard München","is_correct":true}],"explanation":"Bastard München, Noel Noa''s German powerhouse — where Isagi plays beside Michael Kaiser."}]'::jsonb,
  null,
