values (
  'en-dandadan-trivia',
  'Dandadan Trivia: Ghosts, Aliens and Chaos',
  'Ghosts are real, aliens are real and even a maneki-neko ends up possessed. How much do you know about Momo and Okarun''s chaos?',
  'trivia',
  'medium',
  'en',
  (select id from public.categories where slug = 'anime-manga'),
  '[{"id":"q1","question":"Which studio animates the Dandadan anime?","options":[{"id":"a","text":"MAPPA","is_correct":false},{"id":"b","text":"Science SARU","is_correct":true},{"id":"c","text":"Ufotable","is_correct":false},{"id":"d","text":"WIT Studio","is_correct":false}],"explanation":"Science SARU, the studio behind Devilman Crybaby, adapts Yukinobu Tatsu''s manga."},{"id":"q2","question":"Momo Ayase believes in ghosts — what does she think of aliens?","options":[{"id":"a","text":"She hunts them","is_correct":false},{"id":"b","text":"She doesn''t believe in them","is_correct":true},{"id":"c","text":"She''s terrified of them","is_correct":false},{"id":"d","text":"She is one","is_correct":false}],"explanation":"Momo trusts her medium grandmother''s craft; Okarun is the one obsessed with UFOs."},{"id":"q3","question":"Which yokai curses Okarun in the series'' first case?","options":[{"id":"a","text":"Acrobatic Silky","is_correct":false},{"id":"b","text":"Evil Eye","is_correct":false},{"id":"c","text":"Turbo Granny","is_correct":true},{"id":"d","text":"The Flatwoods Monster","is_correct":false}],"explanation":"Turbo Granny, the tunnel spirit — and the Flatwoods Monster is an alien, not a yokai."},{"id":"q4","question":"What object does Turbo Granny''s spirit end up trapped inside?","options":[{"id":"a","text":"A maneki-neko doll","is_correct":true},{"id":"b","text":"A porcelain mask","is_correct":false},{"id":"c","text":"A school backpack","is_correct":false},{"id":"d","text":"An old TV","is_correct":false}],"explanation":"She''s sealed inside a beckoning cat doll and sticks around as the group''s grumpy mascot."},{"id":"q5","question":"What is Momo''s grandmother Seiko''s job?","options":[{"id":"a","text":"Police detective","is_correct":false},{"id":"b","text":"TV spirit medium","is_correct":true},{"id":"c","text":"Shrine maiden","is_correct":false},{"id":"d","text":"School nurse","is_correct":false}],"explanation":"Seiko is a famous — and very real — spirit medium who raises the barriers that save the kids."},{"id":"q6","question":"What is Okarun''s real name?","options":[{"id":"a","text":"Ken Takakura","is_correct":true},{"id":"b","text":"Jin Enjoji","is_correct":false},{"id":"c","text":"Unji Zuma","is_correct":false},{"id":"d","text":"Kinta Sakata","is_correct":false}],"explanation":"Ken Takakura, like the classic actor Momo adores — which is why she refuses to call him by his name."},{"id":"q7","question":"Whose aura grants Aira Shiratori her powers?","options":[{"id":"a","text":"Turbo Granny''s","is_correct":false},{"id":"b","text":"Acrobatic Silky''s","is_correct":true},{"id":"c","text":"A Serpoian''s","is_correct":false},{"id":"d","text":"Evil Eye''s","is_correct":false}],"explanation":"After nearly dying, Aira wakes up carrying Acrobatic Silky''s aura and hair."},{"id":"q8","question":"Which spirit possesses Jiji, Momo''s childhood friend?","options":[{"id":"a","text":"The Dover Demon","is_correct":false},{"id":"b","text":"Evil Eye","is_correct":true},{"id":"c","text":"Turbo Granny","is_correct":false},{"id":"d","text":"The Mongolian Death Worm","is_correct":false}],"explanation":"The Evil Eye bound to Jiji''s house — a grudge that turns him into their most dangerous roommate."}]'::jsonb,
  null,
  array['dandadan', 'dan da dan', 'anime', 'trivia']::text[],
