  '[{"id":"q1","question":"¿Qué estudio anima Dandadan?","options":[{"id":"a","text":"Science SARU","is_correct":true},{"id":"b","text":"MAPPA","is_correct":false},{"id":"c","text":"CloverWorks","is_correct":false},{"id":"d","text":"Toei Animation","is_correct":false}],"explanation":"Science SARU, el estudio de Devilman Crybaby, adapta el manga de Yukinobu Tatsu."},{"id":"q2","question":"Momo Ayase cree en fantasmas. ¿Qué opina de los extraterrestres?","options":[{"id":"a","text":"Los caza","is_correct":false},{"id":"b","text":"No cree en ellos","is_correct":true},{"id":"c","text":"Les tiene terror","is_correct":false},{"id":"d","text":"Ella es uno","is_correct":false}],"explanation":"Momo confía en el oficio de su abuela médium; es Okarun quien jura por los ovnis."},{"id":"q3","question":"¿Qué yokai maldice a Okarun en el primer caso?","options":[{"id":"a","text":"Acrobatic Silky","is_correct":false},{"id":"b","text":"Turbo Granny","is_correct":true},{"id":"c","text":"Evil Eye","is_correct":false},{"id":"d","text":"El Monstruo de Flatwoods","is_correct":false}],"explanation":"La Turbo Granny del túnel; el Monstruo de Flatwoods es un alienígena, no un yokai."},{"id":"q4","question":"¿Dentro de qué queda sellado el espíritu de Turbo Granny?","options":[{"id":"a","text":"Una máscara de porcelana","is_correct":false},{"id":"b","text":"Un televisor viejo","is_correct":false},{"id":"c","text":"Un muñeco maneki-neko","is_correct":true},{"id":"d","text":"Un teléfono","is_correct":false}],"explanation":"Queda encerrada en un gato de la suerte y se convierte en la mascota gruñona del grupo."},{"id":"q5","question":"¿A qué se dedica Seiko, la abuela de Momo?","options":[{"id":"a","text":"Es detective","is_correct":false},{"id":"b","text":"Es sacerdotisa de templo","is_correct":false},{"id":"c","text":"Es médium de televisión","is_correct":true},{"id":"d","text":"Es enfermera escolar","is_correct":false}],"explanation":"Seiko es una médium famosa —y muy real— que levanta las barreras que salvan a los chicos."},{"id":"q6","question":"¿Cuál es el verdadero nombre de Okarun?","options":[{"id":"a","text":"Jin Enjoji","is_correct":false},{"id":"b","text":"Kinta Sakata","is_correct":false},{"id":"c","text":"Ken Takakura","is_correct":true},{"id":"d","text":"Unji Zuma","is_correct":false}],"explanation":"Ken Takakura, como el actor clásico que Momo adora; por eso ella se niega a llamarlo por su nombre."},{"id":"q7","question":"¿De qué yokai hereda Aira su aura y sus poderes?","options":[{"id":"a","text":"De Turbo Granny","is_correct":false},{"id":"b","text":"De Acrobatic Silky","is_correct":true},{"id":"c","text":"De Evil Eye","is_correct":false},{"id":"d","text":"De un serpoiano","is_correct":false}],"explanation":"Al borde de la muerte, Aira despierta con el aura y el cabello de Acrobatic Silky."},{"id":"q8","question":"¿Qué espíritu posee a Jiji, el amigo de infancia de Momo?","options":[{"id":"a","text":"Evil Eye","is_correct":true},{"id":"b","text":"Turbo Granny","is_correct":false},{"id":"c","text":"El Demonio de Dover","is_correct":false},{"id":"d","text":"El Gusano de Mongolia","is_correct":false}],"explanation":"El Evil Eye ligado a la casa de Jiji, un rencor que lo vuelve el compañero más peligroso."}]'::jsonb,
